import re

# Hours come before minutes, each unit at most once, digits optional. The number-less
# alternatives ("h" / "m") are rejected later so the error is an explicit missing number.
_DURATION_RE = re.compile(r"(?:(\d*)\s*h)?(?:(\d*)\s*m)?")


def parse_duration(text: str) -> int:
    """Total minutes of a duration given as hours and/or minutes, e.g. "2h" -> 120,
    "1h30m" -> 90. Units are case-insensitive, in order, at most once each; surrounding
    whitespace is ignored. Anything else raises ValueError."""
    cleaned = text.strip()
    match = _DURATION_RE.fullmatch(cleaned, flags=re.IGNORECASE)
    if match is None:
        raise ValueError(f"invalid duration: {text!r}")
    hours_part, minutes_part = match.groups()
    if hours_part is None and minutes_part is None:
        raise ValueError(f"invalid duration: {text!r}")
    hours = _parse_number(hours_part, "h", text)
    minutes = _parse_number(minutes_part, "m", text)
    return hours * 60 + minutes


def _parse_number(digits: str | None, unit: str, text: str) -> int:
    if digits is None:
        return 0
    if not digits:
        raise ValueError(f"missing number for {unit!r} in {text!r}")
    return int(digits)
